installation.script:
#!/bin/bash

echo "🚀 Installation Node.js NeoHeberg..."

mkdir -p /mnt/server
cd /mnt/server

if [ ! -f package.json ]; then
cat > package.json << 'EOF'
{
  "name": "neoheberg-nodejs-app",
  "version": "1.0.0",
  "main": "index.js",
  "scripts": {
    "start": "node index.js"
  },
  "dependencies": {}
}
EOF
fi

if [ ! -f index.js ]; then
cat > index.js << 'EOF'
const http = require('http');

// 🔥 Port récupéré via Pterodactyl
const port = process.env.SERVER_PORT;

if (!port) {
  console.error("❌ Aucun port trouvé.");
  process.exit(1);
}

const server = http.createServer((req, res) => {
  res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
  res.end(`
    <div style="font-family: Arial; text-align: center; padding: 40px;">
      <h1>🚀 Serveur Node.js NeoHeberg</h1>
      <p>✅ Serveur en ligne</p>
      <p><strong>Node:</strong> ${process.version}</p>
      <p><strong>Port:</strong> ${port}</p>
    </div>
  `);
});

server.listen(port, '0.0.0.0', () => {
  console.clear();
  const now = new Date().toLocaleString('fr-FR', { timeZone: 'Europe/Paris' });

  // Codes couleur ANSI (optionnels, mais rendent l'affichage plus sympa)
  const reset = '\x1b[0m';
  const cyan = '\x1b[36m';

  console.log(`${cyan}┌─────────────────────────────────────────────┐${reset}`);
  console.log(`${cyan}│       🚀 NeoHeberg Node.js                   │${reset}`);
  console.log(`${cyan}├─────────────────────────────────────────────┤${reset}`);
  console.log(`${cyan}│   🔥 Node version : ${process.version.padEnd(21)}    │${reset}`);
  console.log(`${cyan}│   🚪 Port : ${port.toString().padEnd(28)}     │${reset}`);
  console.log(`${cyan}│   🕒 Démarré à : ${now.padEnd(22)}      │${reset}`);
  console.log(`${cyan}├─────────────────────────────────────────────┤${reset}`);
  console.log(`${cyan}│   © 2026 NeoHeberg - Tous droits réservés   │${reset}`);
  console.log(`${cyan}│   Fait avec ❤️ par NeoHeberg                 │${reset}`);
  console.log(`${cyan}└─────────────────────────────────────────────┘${reset}`);
});

process.on('SIGTERM', () => {
  server.close(() => process.exit(0));
});
EOF
fi

echo "✅ Installation terminée."
